// Year 4 English quiz candidates. Three or more reviewed items per built topic.
// English items do not speak by default: the skill being sampled is reading, so
// nothing reads out a passage, a target word or an answer. Spelling is sampled
// without dictation (choose the correct spelling, or complete a word from a clue).
// Each practice target is the challenge slot that teaches that skill.
import { defineAssessmentBank } from "../../curriculumJourneyAuthoring.js";

const SPELT = "Which word is spelt correctly?";
const RIGHT = "Spelt correctly";
const WRONG = "Spelt wrongly";

const RECYCLE = { title: "Recycling Paper", text: "Every week, our school fills three big bins with paper. Most of it is only used once and then thrown away.\n\nPaper can be recycled. It is soaked, turned into pulp and pressed into new sheets. This saves trees and uses less energy than making paper from scratch.\n\nOur class has decided to help. We will collect used paper in a box and ask the caretaker to send it to the recycling centre." };
const JO = { title: "The Gate", text: "Jo stood at the school gate for ages. Other children ran past her, laughing. Mrs Patel stood by the door in a blue coat. Jo held her new lunchbox tightly against her chest and stared at the ground.\n\"Come on, Jo,\" called Mrs Patel. Jo took a tiny step forward and stopped again." };
const SEALS = { title: "Seals", text: "Seals\n\nWhat seals eat\nSeals eat fish, squid and crabs.\n\nWhere seals live\nSeals live in cold seas and on rocky shores.\n\n[Labelled diagram: flipper, whiskers, tail]" };
const MOUSE = { title: "The Lion and the Mouse", text: "The lion lay snoring in the long grass. A tiny mouse scampered over his paw and woke him. \"Please let me go,\" squeaked the mouse. \"One day I may help you.\"\nThe lion laughed, but he let her go. Weeks later, the lion was trapped in a hunter's net. The mouse heard his roars, hurried over and gnawed through the ropes until he was free." };
const CLOCK = { title: "The Clock", text: "Tick tock, goes the clock,\nIn the hall by the door.\nTick tock, goes the clock,\nIt ticks and it ticks some more." };
const FOG = { title: "Fog", text: "Fog\nCreeps over the harbour\nSoftly swallowing boats\nUntil only the bells are left" };
const BOAT = { title: "The Paper Boat", text: "Sasha sailed a paper boat\nDown the stream so wide,\nA frog hopped on to join the trip\nAnd off they went with the tide." };

